import React, { useState } from 'react';
import { useNavigate } from 'react-router-dom';
import Navbar from './Navbar';

const Login = () =>
{
    const navigate = useNavigate();
    const [formData, setFormData] = useState({
        role: "",
        email: "",
        password: ""
    });

    const handleSubmit = async (e) =>
    {
        e.preventDefault();

        try
        {
            const response = await fetch('http://localhost:3000/api/auth/login', {
                method: 'POST',
                headers: {
                    'Content-Type': 'application/json',
                },
                body: JSON.stringify({
                    ...formData,
                }),
            });

            const data = await response.json();
            if (response.ok)
            {
                localStorage.setItem("token", data.token);
                navigate("/dashboard");
            } else
            {
                alert(data.message);
            }
        } catch (error)
        {
            console.error("Login error:", error);
        }
    };

    return (
        <>
            <Navbar />
            <div className="container mx-auto py-10">
                <h1 className="text-2xl font-bold mb-6 text-center">Login</h1>
                <form onSubmit={handleSubmit} className="space-y-4 p-4 bg-white rounded-lg shadow">

                    <div>
                        <label className="block text-sm font-medium text-gray-700">Role</label>
                        <select
                            required
                            value={formData.role}
                            onChange={(e) => setFormData({ ...formData, role: e.target.value })}
                            className="mt-1 block w-full rounded-md border-gray-300 shadow-sm focus:border-indigo-500 focus:ring-indigo-500"
                        >
                            <option value="">Select Role</option>
                            <option value="patient">Patient</option>
                            <option value="doctor">Doctor</option>
                            <option value="ngo">NGO</option>
                        </select>
                    </div>

                    <div>
                        <label className="block text-sm font-medium text-gray-700">Email</label>
                        <input
                            type="email"
                            required
                            value={formData.email}
                            onChange={(e) => setFormData({ ...formData, email: e.target.value })}
                            className="mt-1 block w-full rounded-md border-gray-300 shadow-sm focus:border-indigo-500 focus:ring-indigo-500"
                        />
                    </div>

                    <div>
                        <label className="block text-sm font-medium text-gray-700">Password</label>
                        <input
                            type="password"
                            required
                            value={formData.password}
                            onChange={(e) => setFormData({ ...formData, password: e.target.value })}
                            className="mt-1 block w-full rounded-md border-gray-300 shadow-sm focus:border-indigo-500 focus:ring-indigo-500"
                        />
                    </div>

                    <button
                        type="submit"
                        className="w-full bg-indigo-600 text-white py-2 px-4 rounded-md hover:bg-indigo-700 focus:outline-none focus:ring-2 focus:ring-indigo-500 focus:ring-offset-2"
                    >
                        Login
                    </button>
                </form>
            </div>
        </>
    );
};

export default Login;

import React, { useState } from 'react';

const CreatePost = () => {
  const [formData, setFormData] = useState({
    content: '',
    imageUrl: [''],
    reportUrl: [''],
    medicalHistory: '',
  });
  const [isLoading, setIsLoading] = useState(false);

  const handleAddField = (field) => {
    setFormData(prev => ({
      ...prev,
      [field]: [...prev[field], '']
    }));
  };

  const handleRemoveField = (field, index) => {
    setFormData(prev => ({
      ...prev,
      [field]: prev[field].filter((_, i) => i !== index)
    }));
  };

  const handleFieldChange = (field, index, value) => {
    setFormData(prev => ({
      ...prev,
      [field]: prev[field].map((item, i) => (i === index ? value : item))
    }));
  };

  const handleSubmit = async (e) => {
    e.preventDefault();
    setIsLoading(true);

    try {
      const response = await fetch('http://localhost:3000/api/patient/posts', {
        method: 'POST',
        headers: {
          'Content-Type': 'application/json',
        },
        body: JSON.stringify(formData),
      });

      if (response.ok) {
        setFormData({
          content: '',
          imageUrl: [''],
          reportUrl: [''],
          medicalHistory: '',
        });
        alert("Successfully Posted!")
      }
    } catch (error) {
      console.error('Error creating post:', error);
    } finally {
      setIsLoading(false);
    }
  };

  return (
    <form onSubmit={handleSubmit} className="space-y-4 bg-white p-6 rounded-lg shadow">
      <div>
        <label className="block text-sm font-medium text-gray-700">Description</label>
        <textarea
          value={formData.content}
          onChange={(e) => setFormData(prev => ({ ...prev, content: e.target.value }))}
          className="mt-1 block w-full rounded-md border-gray-300 shadow-sm focus:border-indigo-500 focus:ring-indigo-500"
          rows={3}
          required
        />
      </div>

      <div>
        <label className="block text-sm font-medium text-gray-700">Medical History</label>
        <textarea
          value={formData.medicalHistory}
          onChange={(e) => setFormData(prev => ({ ...prev, medicalHistory: e.target.value }))}
          className="mt-1 block w-full rounded-md border-gray-300 shadow-sm focus:border-indigo-500 focus:ring-indigo-500"
          rows={2}
        />
      </div>

      <div>
        <label className="block text-sm font-medium text-gray-700">Image URLs</label>
        {formData.imageUrl.map((url, index) => (
          <div key={index} className="flex gap-2 mt-2">
            <input
              type="text"
              value={url}
              onChange={(e) => handleFieldChange('imageUrl', index, e.target.value)}
              className="flex-1 rounded-md border-gray-300 shadow-sm focus:border-indigo-500 focus:ring-indigo-500"
              required
            />
            <button
              type="button"
              onClick={() => handleRemoveField('imageUrl', index)}
              className="px-2 py-1 text-red-600 hover:text-red-800"
            >
              Remove
            </button>
          </div>
        ))}
        <button
          type="button"
          onClick={() => handleAddField('imageUrl')}
          className="mt-2 text-sm text-indigo-600 hover:text-indigo-800"
        >
          Add Image URL
        </button>
      </div>

      <div>
        <label className="block text-sm font-medium text-gray-700">Report URLs</label>
        {formData.reportUrl.map((url, index) => (
          <div key={index} className="flex gap-2 mt-2">
            <input
              type="text"
              value={url}
              onChange={(e) => handleFieldChange('reportUrl', index, e.target.value)}
              className="flex-1 rounded-md border-gray-300 shadow-sm focus:border-indigo-500 focus:ring-indigo-500"
              required
            />
            <button
              type="button"
              onClick={() => handleRemoveField('reportUrl', index)}
              className="px-2 py-1 text-red-600 hover:text-red-800"
            >
              Remove
            </button>
          </div>
        ))}
        <button
          type="button"
          onClick={() => handleAddField('reportUrl')}
          className="mt-2 text-sm text-indigo-600 hover:text-indigo-800"
        >
          Add Report URL
        </button>
      </div>

      <button
        type="submit"
        disabled={isLoading}
        className="w-full bg-indigo-600 text-white py-2 px-4 rounded-md hover:bg-indigo-700 focus:outline-none focus:ring-2 focus:ring-indigo-500 focus:ring-offset-2 disabled:opacity-50"
      >
        {isLoading ? 'Creating...' : 'Create Post'}
      </button>
    </form>
  );
};

export default CreatePost;

